for (const item of $input.all()) {
  // Helper: parse JSON string safely
  const safeJsonParse = (value) => {
    if (typeof value === 'string') {
      try {
        return JSON.parse(value);
      } catch (e) {
        return value; // Not valid JSON, keep original
      }
    }
    return value; // Already parsed or not a string
  };

  // Parse watchFile
  if (item.json?.watchFile) {
    item.json.watchFile = safeJsonParse(item.json.watchFile);
  }

  // Parse conversation
  if (item.json?.conversation) {
    item.json.conversation = safeJsonParse(item.json.conversation);
  }

  // Parse context
  if (item.json?.context) {
    item.json.context = safeJsonParse(item.json.context);

    if (typeof item.json.context.BusNameStamp !== 'string') {
      item.json.context.BusNameStamp = JSON.stringify(item.json.context.BusNameStamp);
    }

    if (typeof item.json.context.RouterContextStamp !== 'string') {
      item.json.context.RouterContextStamp = JSON.stringify(item.json.context.RouterContextStamp);
    }

    if (typeof item.json.context.TenantStamp !== 'string') {
      item.json.context.TenantStamp = JSON.stringify(item.json.context.TenantStamp);
    }
  }

  // Default language
  item.json.language = item.json?.language || 'en';
}

return $input.all();

