{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "required": ["subQuestions", "decompositionRationale"],
  "properties": {
    "subQuestions": {
      "type": "array",
      "description": "List of sub-questions (minimum 1 required)",
      "items": {
        "type": "object",
        "required": ["questionFR", "questionEN", "contextFR", "contextEN", "monitoringDimension", "priority", "expectedOutputType"],
        "properties": {
          "questionFR": {
            "type": "string",
            "description": "Question in French (non-empty)"
          },
          "questionEN": {
            "type": "string",
            "description": "Question in English (non-empty)"
          },
          "contextFR": {
            "type": "string"
          },
          "contextEN": {
            "type": "string"
          },
          "monitoringDimension": {
            "type": "string",
            "enum": ["competitive", "strategic", "commercial", "technological", "regulatory"]
          },
          "priority": {
            "type": "integer",
            "description": "Priority level (0-100)"
          },
          "expectedOutputType": {
            "type": "string"
          }
        },
        "additionalProperties": false
      }
    },
    "decompositionRationale": {
      "type": "object",
      "required": ["approachFR", "approachEN"],
      "properties": {
        "approachFR": {
          "type": "string"
        },
        "approachEN": {
          "type": "string"
        }
      },
      "additionalProperties": false
    }
  },
  "additionalProperties": false
}

